-- ===== U13 vocab 覆盖灌库(volume='9',45词)。分步跑。=====

SELECT 'U13 灌前' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U13';

DELETE FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U13';
SELECT 'U13 DELETE后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U13';  -- 应0


SELECT 'U13 INSERT后' tag, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U13';  -- 应45
SELECT word, count(*) FROM public.junior_vocab WHERE grade=9 AND volume='9' AND unit='U13' GROUP BY word HAVING count(*)>1;  -- 查重应0行